UPDATE seal.processing_activity_version
   SET workflow_status = 'SUPERSEDED', updated_by = #{actorId},
       updated_at = CURRENT_TIMESTAMP, version_no = version_no + 1
 WHERE processing_activity_id = #{processingActivityId}
   AND processing_activity_version_id <> #{approvedVersionId}
   AND workflow_status = 'APPROVED'
